var app = new Application();
var textbox = new Textbox(app);
var get = (id) => document.getElementById(id);
var onClick = onClick$1;
var textboxList = get("textboxList");
var mainBox = get("config");
var canvasBox = get("canvasBox");
var canvasParent = get("canvasGoesHere");
var builderNode = get("textboxBuilder");
var configTemplate = builderNode.cloneNode(true);
configTemplate.removeAttribute("id");
configTemplate.removeAttribute("style");
builderNode.remove();
var sequence = new TextboxSequence(textboxList, configTemplate, textbox);
window.PIXI = lib_exports;
window.app = app;
window.textbox = textbox;
window.utils = utils_exports;
window.exporter = export_exports;
window.sequence = sequence;
app.init({
	width: 600 * Textbox.SCALE,
	height: 125 * Textbox.SCALE,
	backgroundAlpha: 0
}).then(async () => {
	canvasParent.appendChild(app.canvas);
	await textbox.init(app);
	onClick(canvasParent, () => {
		if (fullscreenColorPicker.isVisible()) return;
		sequence.advanceSequence();
	});
	app.stage.addChild(textbox.container);
	await importSample();
	onClick("addNewTextbox", () => {
		sequence.add(null, true);
	});
});
window.addEventListener("resize", () => {
	pickerPopups.forEach((x) => {
		if (x.isVisible()) x.link();
	});
});
mainBox.parentElement.addEventListener("scroll", () => {
	pickerPopups.forEach((x) => {
		if (x.isVisible()) x.link();
	});
});
get("canvasResizer").addEventListener("pointerdown", (e) => {
	let y = e.clientY;
	let h = canvasBox.offsetHeight;
	let mobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
	let resize = (e) => {
		let px = h + e.clientY - y;
		if (mobile) return canvasBox.style.setProperty("--boxHeight", px + "px");
		let vh = px / window.innerHeight * 100;
		canvasBox.style.setProperty("--boxHeight", vh + "vh");
	};
	let stopResize = () => {
		document.removeEventListener("pointermove", resize);
		document.removeEventListener("pointerup", stopResize);
	};
	document.addEventListener("pointermove", resize);
	document.addEventListener("pointerup", stopResize);
});
var rightMenu = get("rightMenu");
var rightMenuF = get("rightMenuFullscreen");
var duration = +window.getComputedStyle(canvasBox).getPropertyValue("--fullscreenDuration").slice(0, -1);
var isAnimatingFullscreen = false;
[get("fullscreen"), get("unfullscreen")].forEach((x) => onClick(x, () => {
	if (isAnimatingFullscreen) return;
	let expanded = canvasBox.classList.contains("expanded");
	hide(expanded ? rightMenuF : rightMenu);
	show(expanded ? rightMenu : rightMenuF);
	requestAnimationFrame(() => {
		mainBox.parentElement.inert = !expanded;
		canvasBox.classList.toggle("expanded", !expanded);
		canvasBox.classList.add("animating");
		isAnimatingFullscreen = true;
	});
	setTimeout(() => {
		canvasBox.classList.remove("animating");
		isAnimatingFullscreen = false;
	}, (duration + .01) * 1e3);
}));
var fullscreenColButton = get("fullscreenBG");
onClick(fullscreenColButton, () => {
	fullscreenColorPicker.toggle(fullscreenColButton, null, true);
});
var sampleList = samples_default.split("\n").map((x) => x.split("|").map((z) => z.trim())).filter((x) => x.length > 1);
function getSample() {
	let sample = sampleList[Math.floor(Math.random() * sampleList.length)];
	return {
		message: sample[1].replace("\\n", "\n"),
		portrait: +sample[0]
	};
}
async function importSample() {
	return await importSequence(sequence, { textboxes: [getSample()] });
}
window.importSample = importSample;
var importer = get("sequenceImporter");
importer.addEventListener("change", async (e) => {
	let file = e.target.files[0];
	if (!file) return;
	importer.value = null;
	function fail(msg) {
		alert(msg);
	}
	let text = await file.text().catch(() => null);
	if (!text) fail("Couldn't read this file!");
	let json;
	try {
		json = JSON.parse(text);
	} catch {
		return fail("Couldn't parse this file!");
	}
	if (!json || !json.textboxes || !json.textboxes.length) return fail("This sequence has no textboxes!");
	hideExportPage();
	await importSequence(sequence, json);
});
var saving = false;
function thumbsUp(btn, src, time = 1e3) {
	btn.children[0].setAttribute("src", assets + "button_copied.png");
	btn.setAttribute("disabled", "");
	setTimeout(() => {
		btn.children[0].setAttribute("src", src);
		btn.removeAttribute("disabled");
	}, time);
}
var copyBtn = get("copyButton");
var copySrc = copyBtn.children[0].getAttribute("src");
onClick(copyBtn, async () => {
	if (copyBtn.getAttribute("disabled") !== null) return;
	if (saving) return;
	saving = true;
	if (await textbox.copyToClipboard()) thumbsUp(copyBtn, copySrc);
	saving = false;
});
var downloadBtn = get("downloadButton");
var downloadSrc = downloadBtn.children[0].getAttribute("src");
onClick(downloadBtn, async () => {
	if (downloadBtn.getAttribute("disabled") !== null) return;
	if (saving) return;
	saving = true;
	if (await textbox.download()) thumbsUp(downloadBtn, downloadSrc);
	saving = false;
});
onClick("saveSequence", () => downloadSequence(sequence));
var sequenceImporter = get("sequenceImporter");
onClick("loadSequence", () => sequenceImporter.click());
var exportBox = get("export");
var exportCode = get("exportCode");
var codeBtn = get("toCode");
var hideCodeBtn = get("toNotCode");
var exportDetailsParent = get("exportDetails");
var exportDetails = exportDetailsParent.querySelectorAll("div");
onClick(codeBtn, () => showExportPage());
onClick(hideCodeBtn, () => hideExportPage());
var exportButtons = document.querySelectorAll(".exportTypes button");
exportButtons.forEach((x) => {
	onClick(x, (e) => {
		let type = x.getAttribute("export");
		if (!type || e.isTrusted && x.classList.contains("selected")) return;
		document.querySelectorAll(".exportTypes button.selected").forEach((b) => b.classList.remove("selected"));
		x.classList.add("selected");
		let foundDetails = false;
		exportDetails.forEach((d) => {
			if (d.getAttribute("export") == type) {
				foundDetails = true;
				show(d);
			} else hide(d);
		});
		foundDetails ? show(exportDetailsParent) : hide(exportDetailsParent);
		switch (type) {
			case "cts": return exportCode.value = toCustomTextboxesJSON(sequence);
			case "geode": return exportCode.value = toGeodeCPP(sequence);
			case "site": return exportCode.value = downloadSequence(sequence, true);
		}
	});
});
function showExportPage() {
	hide(mainBox);
	hide(codeBtn);
	show(exportBox);
	show(hideCodeBtn);
	exportButtons[0].click();
	exportBox.scrollTop = 0;
	exportBox.parentElement.scrollTop = 0;
}
function hideExportPage() {
	hide(exportBox);
	hide(hideCodeBtn);
	show(mainBox);
	show(codeBtn);
	exportCode.value = "";
}
var changelogBox = get("changelog");
var changelogText = get("changelogVersions");
function toggleInteraction(enabled) {
	mainBox.parentElement.inert = !enabled;
	canvasBox.inert = !enabled;
}
onClick("version_number", () => {
	show(changelogBox);
	changelogText.scrollTop = 0;
	toggleInteraction(false);
});
changelog_default.split(/^\* /m).slice(1).forEach((v, index) => {
	let lines = v.split("\n").map((z) => z.trim());
	let [number, date] = lines.shift().split("-").map((z) => z.trim());
	let msg = document.createElement("p");
	msg.innerHTML = `<span class="ver"><b>${number}</b> (${date})</span><br>${lines.join("<br>")}`;
	changelogText.appendChild(msg);
	if (index == 0) {
		get("version_number").textContent = number;
		get("version_date").textContent = `(${date})`;
	}
});
document.querySelectorAll(".closePopup").forEach((x) => {
	onClick(x, () => closePopups());
});
document.querySelectorAll(".flalert.fragile").forEach((x) => {
	x.addEventListener("click", (e) => {
		if (e.target.classList.contains("fragile")) closePopups();
	});
});
function closePopups() {
	document.querySelectorAll(".flalert").forEach((x) => hide(x));
	toggleInteraction(true);
}
window.onbeforeunload = function(e) {
	if (sequence.sequence.length > 1) {
		e.returnValue = "";
		e.preventDefault();
	}
};
